(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["clinical-pathophysiology-i-exam-2"]={"title":"Clinical Pathophysiology I Exam 2","sections":[{"id":"l6-chd","title":"L6 · Coronary Heart Disease & Ischemia","style":"--acc:#6e1f2f;--acc-bg:#ebe0e2;--acc-zebra:#f5eff0;--acc-ink:#561825"},{"id":"l6-plaque","title":"L6 · Lipoproteins, Atherosclerosis & Plaque","style":"--acc:#8a5a14;--acc-bg:#efe8de;--acc-zebra:#f7f3ef;--acc-ink:#6c4610"},{"id":"l6-acs","title":"L6 · Angina & Acute Coronary Syndrome","style":"--acc:#a23a4c;--acc-bg:#f2e3e6;--acc-zebra:#f8f1f2;--acc-ink:#7e2d3b"},{"id":"l6-valves","title":"L6 · Valve Disease","style":"--acc:#2f5f6b;--acc-bg:#e2e9ea;--acc-zebra:#f0f4f5;--acc-ink:#254a53"},{"id":"l6-myo","title":"L6 · Infective, Myocardial & Pericardial","style":"--acc:#5a3a6e;--acc-bg:#e8e3eb;--acc-zebra:#f3f1f5;--acc-ink:#462d56"},{"id":"l7-structure","title":"L7 · Vessel Anatomy & Function","style":"--acc:#1f5a73;--acc-bg:#e0e8eb;--acc-zebra:#eff3f5;--acc-ink:#18465a"},{"id":"l7-wall","title":"L7 · Wall Injury, Vessel Size & Blood Pressure","style":"--acc:#2e6b4f;--acc-bg:#e2eae6;--acc-zebra:#f0f5f3;--acc-ink:#24533e"},{"id":"l7-athero","title":"L7 · Arteriosclerosis & Atherosclerosis","style":"--acc:#7a4a1f;--acc-bg:#ece6e0;--acc-zebra:#f6f2ef;--acc-ink:#5f3a18"},{"id":"l7-aneurysm","title":"L7 · Aneurysm & Dissection","style":"--acc:#6b2d5c;--acc-bg:#eae2e8;--acc-zebra:#f5f0f4;--acc-ink:#532348"},{"id":"l7-other","title":"L7 · Other Arterial Disease & Veins","style":"--acc:#3d4f7a;--acc-bg:#e4e6ec;--acc-zebra:#f1f3f6;--acc-ink:#303e5f"}],"rows":[{"t":"Coronary heart disease","d":"Insufficient delivery of oxygenated blood to the myocardium because of ATHEROSCLEROTIC coronary arteries. About 50% of cardiovascular deaths. Also called ischemic heart disease, coronary artery disease.","s":0},{"t":"Ischemia = supply vs demand","d":"Begins when oxygen SUPPLY &lt; DEMAND → less ATP (adenosine triphosphate). Causes abnormal function AND abnormal rhythms; prolonged → irreversible damage.","s":0},{"t":"Supply falls","d":"Large plaques · acute platelet aggregation then thrombosis · VASOSPASM · abnormal microcirculation · poor perfusion pressure.","s":0},{"t":"Demand rises","d":"Workload = HEART RATE · PRELOAD · AFTERLOAD · CONTRACTILITY. Raise any one → more oxygen demand.","s":0},{"t":"Etiologies","d":"ATHEROSCLEROSIS behind almost all → predisposes to thrombosis, vasospasm, endothelial dysfunction. Microcirculation: small-vessel endothelium regulates flow abnormally. Uncommon: low blood oxygen content (respiratory); poor perfusion (hypotension, hypovolemia).","s":0},{"t":"Major risk factors","d":"Age · family history · abnormal lipids · smoking · hypertension · diabetes mellitus · obesity.","s":0},{"t":"Probable risk factors","d":"Male sex · HOMOCYSTEINE · high-sensitivity C-reactive protein.","s":0},{"t":"Collateral circulation","d":"Develops when plaque builds over YEARS — why slow occlusion is tolerated better than sudden.","s":0},{"t":"Flow tracks demand","d":"Myocardial oxygen consumption and blood flow correspond NEARLY LINEARLY; METABOLIC SIGNALS are the principal determinants of delivery.","s":0},{"t":"Coronary anatomy","d":"LEFT MAIN → left anterior descending (anterior interventricular) + CIRCUMFLEX. RIGHT CORONARY → marginal + posterior interventricular.","s":0},{"t":"Frank–Starling","d":"More diastolic filling → more ejected. Force ∝ initial sarcomere length (preload). Maximal force at 2.6 micrometers, rarely exceeded in the normal heart.","s":0},{"t":"Low-density lipoprotein","d":"Cholesterol-rich → HIGHEST risk.","s":1},{"t":"Very-low-density lipoprotein","d":"Triglyceride-rich → INCREASES risk.","s":1},{"t":"High-density lipoprotein","d":"DECREASES risk — carries cholesterol BACK TO THE LIVER, away from plaque.","s":1},{"t":"Familial hypercholesterolemia","d":"Most common genetic hyperlipidemia. Defective LOW-DENSITY LIPOPROTEIN RECEPTOR on liver cells → liver cannot clear cholesterol.","s":1},{"t":"Homocysteine","d":"Amino acid from METHIONINE → CYSTEINE. Atherogenic + prothrombotic: intimal thickening, elastic lamina disruption, smooth muscle hypertrophy, platelet accumulation, platelet-rich occlusive thrombus.","s":1},{"t":"Plaque sequence","d":"ENDOTHELIAL INJURY (wall stress, toxins, inflammation, hyperlipidemia) → permeable endothelium, leukocytes recruited → low-density lipoprotein leaks in and is OXIDIZED → FOAM CELLS → mediators + growth factor → smooth muscle proliferation → LIPID CORE → collagen/fibrin CAP.","s":1},{"t":"75%","d":"Occlusion at which blood flow is COMPROMISED.","s":1},{"t":"Vulnerable plaque (slide 24, image only)","d":"LARGE lipid core · THIN fibrous cap · rich in MACROPHAGES · increased MMPs (matrix metalloproteinases) · POOR in smooth muscle · LOW-GRADE stenosis.","s":1},{"t":"Stable vs vulnerable","d":"Stable: thick cap, small core, many smooth muscle cells. Vulnerable: thin cap, large core, many macrophages. Smooth muscle BUILDS the cap; macrophages DIGEST it.","s":1},{"t":"Why plaques rupture","d":"Composition + mechanical stress. Trigger: SHEAR from high-velocity flow through a severe stenosis. VASA VASORUM capillaries hemorrhage → pressure builds inside the plaque.","s":1},{"t":"Rupture consequences","d":"Exposed subendothelial proteins → platelet aggregation → THROMBUS; EMBOLI block smaller vessels downstream.","s":1},{"t":"Coronary syndromes","d":"CHRONIC: stable angina, ischemic cardiomyopathy. ACUTE: unstable angina, myocardial infarction. Classified by severity and onset.","s":2},{"t":"Angina pectoris","d":"Intermittent ischemia NOT enough to kill cells; when demand rises; may cause pulmonary congestion.","s":2},{"t":"Stable (typical)","d":"MOST COMMON. Fixed stenosis → ischemia only under increased WORKLOAD.","s":2},{"t":"Prinzmetal (variant)","d":"VASOSPASM (cause unknown). Unpredictable; NO relation to physical or emotional stress.","s":2},{"t":"Unstable (crescendo)","d":"May progress to acute ischemia → counted with the ACUTE coronary syndromes.","s":2},{"t":"Acute coronary syndrome","d":"Unstable angina + myocardial infarction (hard to tell apart clinically). Pain longer than typical angina; PLAQUE RUPTURE + ACUTE THROMBOSIS.","s":2},{"t":"Infarction mechanism","d":"Prolonged/total loss of flow → NECROSIS or APOPTOSIS. Thrombus on a cracked plaque → platelet plug → clotting cascade → occlusion. Outcome depends on COLLATERALS, WORKLOAD, TIME.","s":2},{"t":"Occlusion timeline","d":"Immediately: ATP depleted. Few minutes: cannot contract. AFTER 30 MINUTES: irreversible necrosis.","s":2},{"t":"Location","d":"Nearly all in LEFT VENTRICLE. Left anterior descending 40–50% · right coronary 30–40% · left circumflex 15–20%.","s":2},{"t":"Gross changes","d":"6 h: first visible · 18–24 h: paler · then yellow, soft, red vascular border · 1–2 weeks: necrotic tissue removed · by 6 weeks: fibrous scar.","s":2},{"t":"Stenosis vs regurgitation","d":"STENOSIS = fails to OPEN → PRESSURE work, gradient across valve. REGURGITATION = fails to CLOSE → VOLUME work.","s":3},{"t":"Stenosis facts","d":"Hemodynamics affected at 50% closure; slow → compensatory HYPERTROPHY. Causes: RHEUMATIC scarring, aging CALCIFICATION.","s":3},{"t":"Regurgitation facts","d":"Acute: infection or PAPILLARY MUSCLE RUPTURE. Causes: rheumatic heart disease, infective endocarditis.","s":3},{"t":"Mitral stenosis","d":"DIASTOLIC left atrial &gt; left ventricular gradient. Left atrial congestion/pressure ↑, pulmonary pressure ↑, stroke volume ↓ → pulmonary hypertension → right heart failure. Late: ATRIAL FIBRILLATION, atrial enlargement, ATRIAL CLOTS.","s":3},{"t":"Mitral regurgitation","d":"SYSTOLIC backflow into atrium. HIGH AFTERLOAD INCREASES it. Atrium AND ventricle dilate + hypertrophy; severe → left heart failure.","s":3},{"t":"Mitral valve prolapse","d":"BALLOONING into left atrium in systole. Usually silent; sometimes some regurgitation.","s":3},{"t":"Aortic stenosis","d":"Most often AGE-RELATED CALCIFICATION; common with BICUSPID valve (slide: clinically apparent over 79). Systolic left ventricle–aortic gradient → LEFT VENTRICULAR HYPERTROPHY → ischemia and ANGINA → failure.","s":3},{"t":"Aortic regurgitation","d":"DIASTOLIC leak back into left ventricle. AORTIC ROOT DILATION common (aging, connective tissue disease). Left ventricle hypertrophies + dilates; DIASTOLIC PRESSURE FALLS.","s":3},{"t":"Timing rule","d":"DIASTOLE: mitral stenosis, aortic regurgitation. SYSTOLE: mitral regurgitation, prolapse, aortic stenosis.","s":3},{"t":"Rheumatic heart disease","d":"After GROUP A BETA-HEMOLYTIC STREPTOCOCCUS. IMMUNE attack by CROSS-REACTIVITY; HLA (human leukocyte antigen) predisposition. All layers → carditis. Valves: swelling, erosions, platelets + fibrin, then SCARRING and SHORTENING.","s":4},{"t":"Infective endocarditis","d":"Invasion + colonization of endocardium; BLOODSTREAM INVASION is a prerequisite. VEGETATIONS = organisms in FIBRIN → dysfunction + EMBOLI. Commonest: Streptococcus, Staphylococcus aureus.","s":4},{"t":"Subacute endocarditis","d":"Insidious; needs a PREEXISTING valve lesion. LESS VIRULENT organisms (slide lists S. aureus, Streptococcus, Candida) cannot attack a healthy endocardium. (Textbook generally pairs S. aureus with the acute form.)","s":4},{"t":"Myocarditis","d":"Inflammation + leukocyte infiltration + necrosis. Microbes, immune disease, physical agents; COXSACKIEVIRUS most common in North America. Left ventricular dysfunction, ALL FOUR chambers dilated, edematous muscle, endocardium usually NORMAL.","s":4},{"t":"Dilated cardiomyopathy","d":"Also 'congested'. Dilation of one or both ventricles → failure. ALCOHOL · GENETICS · PREGNANCY · POST-VIRAL.","s":4},{"t":"Hypertrophic cardiomyopathy","d":"Thick, HYPERKINETIC muscle. OUTFLOW OBSTRUCTION + impaired DIASTOLIC FILLING.","s":4},{"t":"Restrictive cardiomyopathy","d":"Stiff, FIBROTIC, noncompliant (e.g. AMYLOIDOSIS) → restricted filling → low stroke volume → failure.","s":4},{"t":"Pericardial effusion types","d":"SEROUS transudate (heart failure, hypoproteinemia) · SEROSANGUINOUS (blunt trauma, heart surgery, cardiopulmonary resuscitation) · CHYLOUS (lymph obstruction) · BLOOD/hemopericardium (penetrating trauma).","s":4},{"t":"Tamponade","d":"Large effusion COMPRESSES chambers from outside → filling impaired. Life-threatening.","s":4},{"t":"Pericarditis","d":"ACUTE: mostly idiopathic, mostly VIRAL. CHRONIC: ADHESIVE mediastinopericarditis (heart stuck to mediastinum → workload ↑) or CONSTRICTIVE (dense scarred sac = STIFF CAGE → impaired diastolic filling).","s":4},{"t":"Not in the deck","d":"Objective m (blood pressure regulation) → see Lecture 7. Objective n (conduction system): no slide; only ischemia → abnormal rhythms, mitral stenosis → atrial fibrillation.","s":4},{"t":"Five components","d":"ARTERIES high pressure, strong walls, fast flow → ARTERIOLES control release into capillaries (main resistance, 'small but mighty') → CAPILLARIES exchange → VENULES collect → VEINS return blood, RESERVOIR, low pressure, thin walls.","s":5},{"t":"Three layers","d":"INTIMA: endothelium on basement membrane + thin matrix. MEDIA: elastin + smooth muscle 'like tree rings', expand in systole, recoil in diastole. ADVENTITIA: loose connective tissue, nerves, its own small arterioles in large vessels.","s":5},{"t":"Capillaries","d":"NO MEDIA. ≈ red cell diameter. Large cross-section, LOW flow → easy exchange. Densest in MYOCARDIUM and BRAIN. Pericytes around them.","s":5},{"t":"Capillary types","d":"CONTINUOUS (least permeable; blood–brain barrier) · FENESTRATED (kidney glomeruli, small intestine) · SINUSOIDAL (leakiest; liver, marrow, spleen, endocrine).","s":5},{"t":"Functions","d":"Nutrients in · wastes out · hormones carried · HOMEOSTASIS of tissue fluid.","s":5},{"t":"Loops","d":"PULMONARY: right heart → lungs. SYSTEMIC: left heart → tissues → right heart. Artery = AWAY from heart, so pulmonary artery carries deoxygenated blood.","s":5},{"t":"Veins hold","d":"About 66% of total blood volume.","s":5},{"t":"Healthy endothelium","d":"NONTHROMBOGENIC; modulates medial tone (resistance); METABOLIZES ANGIOTENSIN; regulates inflammation; controls smooth muscle growth.","s":6},{"t":"Smooth muscle cells","d":"Predominant media cell. Proliferate; make collagen, elastin, proteoglycans, growth factors, cytokines; constrict/dilate.","s":6},{"t":"Neointimal hyperplasia","d":"Injury → smooth muscle MIGRATES INTO INTIMA, proliferates, makes matrix; endothelium regrows with LESS NITRIC OXIDE; platelets activate; leukocytes recruited → thick intima, NARROW LUMEN. Same response to ANY injury.","s":6},{"t":"The twofold problem","d":"Thicker intima narrows the lumen AND lost nitric oxide (a vasodilator) lets it constrict.","s":6},{"t":"Two mechanisms","d":"NARROWING (progressive: atherosclerosis; precipitous: thrombosis, embolism) or WEAKENING (dilation, rupture).","s":6},{"t":"Size predicts disease","d":"LARGE elastic (aorta 2–3.5 cm) → ANEURYSM (elastic loss). MEDIUM muscular (coronary 3–4 mm, renal) → ATHEROSCLEROSIS. SMALL (≤2 mm) + ARTERIOLES (20–100 micrometers) → HYPERTENSION.","s":6},{"t":"Blood pressure","d":"= CARDIAC OUTPUT × VASCULAR RESISTANCE. Resistance set at ARTERIOLES (constrictors vs dilators). Output = rate × stroke volume; volume set by SODIUM (water follows sodium).","s":6},{"t":"Low pressure response","d":"Kidney RENIN (low afferent arteriolar pressure) → angiotensinogen → ANGIOTENSIN I → endothelial catabolism → ANGIOTENSIN II → smooth muscle tone ↑ + ALDOSTERONE ↑ (sodium resorption).","s":6},{"t":"Hypertension risks","d":"Atherosclerosis, congestive heart failure, renal failure, CEREBRAL HEMORRHAGE, AORTIC DISSECTION.","s":6},{"t":"Essential hypertension","d":"90–95%, idiopathic. Genetic + environmental. INSUFFICIENT RENAL SODIUM EXCRETION → volume ↑ → output ↑ → constriction → pressure ↑.","s":6},{"t":"Secondary hypertension","d":"RENOVASCULAR: renal artery stenosis → low afferent pressure → RENIN. PRIMARY HYPERALDOSTERONISM: a common cause.","s":6},{"t":"Arteriosclerosis","d":"'Hardening of the arteries': wall thickening + LOSS OF ELASTICITY. Four patterns below.","s":7},{"t":"Arteriolosclerosis","d":"Small arteries/arterioles; HYPERTENSION. HYALINE = protein-thickened glassy wall, narrow lumen. HYPERPLASTIC = ONION SKINNING (concentric smooth muscle).","s":7},{"t":"Fibromuscular intimal hyperplasia","d":"Muscular arteries; inflammation or mechanical injury; a healing response → IN-STENT RESTENOSIS; limits solid-organ transplants.","s":7},{"t":"Mönckeberg medial sclerosis","d":"CALCIFICATION OF THE MEDIA of muscular arteries; usually NOT clinically significant.","s":7},{"t":"Atherosclerosis","d":"'Gruel' + 'hardening'. MOST clinically relevant. Coronary, cerebral, peripheral disease; about half of Western deaths.","s":7},{"t":"Risk factors","d":"Hyperlipidemia · LIPOPROTEIN(a) (altered low-density lipoprotein, independent of total cholesterol) · smoking · hypertension · diabetes · METABOLIC SYNDROME · C-reactive protein · FAMILY HISTORY = MOST IMPORTANT · age · men + postmenopausal women.","s":7},{"t":"Sequence","d":"Injury → LOW-DENSITY LIPOPROTEIN accumulates → MONOCYTE adhesion → PLATELET adhesion → smooth muscle RECRUITED → proliferation, matrix, T cells → lipid → CALCIFICATION.","s":7},{"t":"Atheroma","d":"Intimal plaque into the lumen: SOFT LIPID CORE + FIBROUS CAP. Stable → ischemia; unstable → rupture, thrombosis, embolism.","s":7},{"t":"★ Peripheral arterial disease","d":"'Do know': stenosis → ischemia → CLAUDICATION when working muscle's demand rises.","s":7},{"t":"Aneurysm vs dissection","d":"ANEURYSM = localized abnormal DILATION. DISSECTION = blood enters a wall defect and TUNNELS through the MEDIA.","s":8},{"t":"Shapes","d":"TRUE saccular (focal bulge, 'berry') · TRUE fusiform (whole circumference) · FALSE (ruptured wall, hematoma held by extravascular tissue) · DISSECTION (intimal tear splits media).","s":8},{"t":"Weakening ≠ rupture","d":"An aneurysm is a WEAK wall, not a ruptured one; rupture risk rises with SIZE (in lecture: under 4 cm rarely, over 5.5 cm very high).","s":8},{"t":"Pathogenesis","d":"Poor connective tissue (defective collagen; abnormal transforming growth factor signaling = MARFAN) · collagen degradation &gt; synthesis (inflammation, proteases) · smooth muscle LOSS (ischemia, hypertension, TERTIARY SYPHILIS).","s":8},{"t":"Predisposing","d":"Atherosclerosis · hypertension · smoking.","s":8},{"t":"Abdominal aortic aneurysm","d":"ATHEROSCLEROTIC; abdominal aorta + common iliac arteries.","s":8},{"t":"Thoracic aortic aneurysm","d":"HYPERTENSION; also Marfan, inflammation.","s":8},{"t":"Aortic dissection","d":"Laminar planes of MEDIA SPLIT → blood channel in the wall. HYPERTENSION = major risk factor.","s":8},{"t":"Cerebral saccular (berry)","d":"Thin/absent media; absent or fragmented internal elastic lamina. LACK OF ELASTIC LAMINA = main feature. Usually acquired.","s":8},{"t":"Fusiform / mycotic","d":"Fusiform: whole circumference (atherosclerosis). MYCOTIC: infected emboli from INFECTIVE ENDOCARDITIS (rare).","s":8},{"t":"Fibromuscular dysplasia","d":"Focal irregular thickening (hyperplasia + fibrosis of MEDIA and INTIMA) of medium/large muscular arteries → stenosis. RENAL arteries. 'STRING OF BEADS' on angiography; may dilate and rupture.","s":9},{"t":"Vasculitis","d":"Vessel wall inflammation, mostly SMALL vessels. Mechanisms: IMMUNE-MEDIATED or DIRECT INFECTIOUS INVASION. Large: giant cell arteritis. Medium: polyarteritis nodosa, Kawasaki. Small: ANCA (anti-neutrophil cytoplasmic antibody) necrotizing; immune complex (lupus, rheumatoid arthritis). Said to go light.","s":9},{"t":"Raynaud phenomenon","d":"EXAGGERATED VASOCONSTRICTION to COLD + STRESS, extremities. WHITE (spasm) → BLUE (anoxia) → RED (oxygenated blood returns).","s":9},{"t":"Arteriovenous fistula","d":"Direct artery–vein link BYPASSING CAPILLARIES: developmental, aneurysm rupturing into a vein, penetrating injury, inflammatory necrosis, surgical (hemodialysis access).","s":9},{"t":"Veins","d":"Larger lumen, THINNER MEDIA (capacitance), VALVES stop gravitational backflow.","s":9},{"t":"Varicose veins","d":"Dilated, tortuous; VALVE INSUFFICIENCY; chronic high intraluminal pressure + weak wall. Superficial (saphenous), legs; also pelvis/rectum.","s":9},{"t":"Esophageal varices / hemorrhoids","d":"Varices: submucosal distal esophageal veins from CIRRHOSIS + PORTAL HYPERTENSION. Hemorrhoids: varicose venous plexus at the ANORECTAL junction.","s":9},{"t":"Deep vein thrombosis","d":"Deep veins (femoral, popliteal, tibial); STASIS in a dilated vein. THIRD most common cardiovascular cause of death.","s":9},{"t":"Deep vein thrombosis risks","d":"Reduced flow (IMMOBILITY) · raised venous pressure · mechanical injury · raised viscosity (dehydration, thrombocytosis) · anatomy · hypercoagulable (cancer, sepsis, lupus, ORAL ESTROGEN).","s":9},{"t":"Virchow triad","d":"VESSEL WALL DAMAGE · FLOW TURBULENCE · HYPERCOAGULABILITY.","s":9},{"t":"Clot fate","d":"Neutrophils + macrophages infiltrate fibrin; COLLAGEN replaces fibrin over weeks → less flow. Dislodges → EMBOLUS → PULMONARY ARTERY = pulmonary embolus.","s":9}],"map":{"clinical-pathophysiology-i-exam-2-cardiac-pathophysiology-quiz-version-2":[0,35,44,35,69,31,37,1,27,7,50,27,0,32,48,36,36,-1,75,0,-1,-1,16,42,6,36,23,47,48,38],"clinical-pathophysiology-i-exam-2-cardiac-pathophysiology-quiz":[50,11,0,22,22,41,42,37,32,41,16,30,36,45,49,16,24,77,32,-1,38,33,45,63,46,3,17,50,-1,12],"clinical-pathophysiology-i-exam-2-vascular-pathophysiology-quiz-version-2":[56,79,97,77,89,75,79,57,70,66,96,70,52,75,96,79,79,65,60,52,76,63,60,90,53,82,68,94,91,86],"clinical-pathophysiology-i-exam-2-vascular-pathophysiology-quiz":[90,54,56,67,66,98,90,90,60,89,60,75,82,93,97,-1,69,63,-1,-1,87,63,95,54,93,65,63,99,65,-1]}};
